# ============================================================
# 09_targeted_motif_enrichment.R
#
# Aim
# ---
# Test enrichment of a defined target-site motif in predicted
# sRNA target genes relative to a genomic background.
#
#
# DEFAULT MOTIF
# -------------
#
#     AAACACAACAT
#
#
# MOTIF CLASSES
# -------------
#
# The script evaluates:
#
#   1. Exact motif match
#   2. Exactly one mismatch
#   3. Exact or one mismatch (<=1 mismatch)
#
# Matching is based on Hamming distance across the complete
# motif length.
#
#
# IMPORTANT
# ---------
#
# Sequence windows generated by Script 08 are already oriented
# in the direction of transcription.
#
# Therefore the motif is searched directly in the oriented
# target sequence. The reverse-complement motif is NOT searched
# separately.
#
#
# WINDOW COORDINATES
# ------------------
#
# Script 08 generated:
#
#       -200 to +100 nt
#
# relative to the CDS start.
#
# FASTA position:
#
#       201 = CDS-relative position 0
#
# Therefore:
#
#       relative coordinate =
#           FASTA position - 201
#
#
# INPUTS
# ------
#
# results/motif/
#   candidate_windows_minus200_plus100.fasta
#   background_windows_minus200_plus100.fasta
#
# results/tables/
#   motif_window_metadata.csv
#
#
# OUTPUTS
# -------
#
# results/tables/
#
#   motif_occurrences.csv
#   motif_window_summary.csv
#   motif_enrichment_summary.csv
#   motif_position_summary.csv
#   motif_sequence_variant_summary.csv
#   motif_enrichment_qc.csv
#
# ============================================================



