# ============================================================
# HELPER: READ FASTA
# ============================================================

read_fasta <- function(
    path,
    dataset_label
) {
  
  lines <- readLines(
    path,
    warn = FALSE
  )
  
  
  header_rows <- which(
    startsWith(
      lines,
      ">"
    )
  )
  
  
  if (length(header_rows) == 0) {
    
    stop(
      "No FASTA records found in:\n",
      path
    )
  }
  
  
  records <- vector(
    "list",
    length(
      header_rows
    )
  )
  
  
  for (
    i in seq_along(
      header_rows
    )
  ) {
    
    header_row <-
      header_rows[i]
    
    
    start_row <-
      header_row +
      1L
    
    
    if (
      i <
      length(
        header_rows
      )
    ) {
      
      end_row <-
        header_rows[i + 1L] -
        1L
      
    } else {
      
      end_row <-
        length(lines)
    }
    
    
    sequence_lines <-
      if (
        start_row <= end_row
      ) {
        
        lines[
          start_row:end_row
        ]
        
      } else {
        
        character(0)
      }
    
    
    sequence <-
      paste0(
        sequence_lines,
        collapse = ""
      )
    
    
    sequence <-
      toupper(
        gsub(
          "[^A-Za-z]",
          "",
          sequence
        )
      )
    
    
    header <-
      sub(
        "^>",
        "",
        lines[
          header_row
        ]
      )
    
    
    reference_locus <-
      strsplit(
        header,
        "\\|"
      )[[1]][1]
    
    
    records[[i]] <-
      tibble::tibble(
        
        dataset =
          dataset_label,
        
        reference_locus =
          reference_locus,
        
        fasta_header =
          header,
        
        sequence =
          sequence,
        
        sequence_length =
          nchar(
            sequence
          )
      )
  }
  
  
  dplyr::bind_rows(
    records
  )
}



