  1L



# ============================================================
# HELPER: HAMMING DISTANCE
# ============================================================

hamming_distance <- function(
    x,
    motif
) {
  
  x_chars <-
    strsplit(
      x,
      "",
      fixed = TRUE
    )[[1]]
  
  
  motif_chars <-
    strsplit(
      motif,
      "",
      fixed = TRUE
    )[[1]]
  
  
  if (
    length(
      x_chars
    ) !=
    length(
      motif_chars
    )
  ) {
    
    stop(
      "Hamming-distance sequences must have equal length."
    )
  }
  
  
  sum(
    x_chars !=
      motif_chars
  )
}



# ============================================================
# HELPER: FIND MOTIF OCCURRENCES
# ============================================================

find_motif_occurrences <- function(
    sequence,
    motif,
    maximum_mismatches
) {
  
  sequence <-
    toupper(
      sequence
    )
  
  
  motif <-
    toupper(
      motif
    )
  
  
  sequence_length <-
    nchar(
      sequence
    )
  
  
  motif_length <-
    nchar(
      motif
    )
  
  
  if (
    sequence_length <
    motif_length
  ) {
    
    return(
      tibble::tibble()
    )
  }
  
  
  starts <-
    seq_len(
      sequence_length -
        motif_length +
        1L
    )
  
  
  out <- vector(
    "list",
    length(
      starts
    )
  )
  
  
  k <- 0L
  
  
  for (
    start_position in starts
  ) {
    
    end_position <-
      start_position +
      motif_length -
      1L
    
    
    observed <-
      substr(
        sequence,
        start_position,
        end_position
      )
    
    
    # Ignore windows containing ambiguous bases.
    
    if (
      !grepl(
        "^[ACGT]+$",
        observed
      )
    ) {
      
      next
    }
    
    
    mismatches <-
      hamming_distance(
        observed,
        motif
      )
    
    
    if (
      mismatches <=
      maximum_mismatches
    ) {
      
      k <- k + 1L
      
      
      out[[k]] <-
        tibble::tibble(
          
          sequence_start =
            start_position,
          
          sequence_end =
            end_position,
          
          matched_sequence =
            observed,
          
          n_mismatches =
            mismatches
        )
    }
  }
  
  
  if (
    k == 0L
  ) {
    
    return(
      tibble::tibble()
    )
  }
  
  
  dplyr::bind_rows(
    out[
      seq_len(k)
    ]
  )
}



# ============================================================
# SEARCH ALL WINDOWS
# ============================================================

