  )
) {
  
  matches <- find_motif_occurrences(
    
    sequence =
      metadata$sequence[i],
    
    motif =
      target_motif,
    
    maximum_mismatches =
      max_mismatches
  )
  
  
  if (
    nrow(matches) == 0
  ) {
    
    occurrence_list[[i]] <-
      NULL
    
    next
  }
  
  
  occurrence_list[[i]] <-
    matches |>
    dplyr::mutate(
      
      dataset =
        metadata$dataset[i],
      
      reference_locus =
        metadata$
        reference_locus[i],
      
      gene =
        metadata$gene[i],
      
      annotation =
        metadata$annotation[i],
      
      strand =
        metadata$strand[i],
      
      .before = 1
    )
}



motif_occurrences <- dplyr::bind_rows(
  occurrence_list
)



# ============================================================
# ADD CDS-RELATIVE MOTIF COORDINATES
# ============================================================

if (
  nrow(
    motif_occurrences
  ) > 0
) {
  
  motif_occurrences <- motif_occurrences |>
    dplyr::mutate(
      
      motif_start_rel_CDS =
        sequence_start -
        cds_start_sequence_position,
      
      motif_end_rel_CDS =
        sequence_end -
        cds_start_sequence_position,
      
      
      match_class =
        dplyr::case_when(
          
          n_mismatches ==
            0L ~
            
            "exact",
          
          
          n_mismatches ==
            1L ~
            
            "one_mismatch",
          
          
          TRUE ~
            
            paste0(
              n_mismatches,
              "_mismatches"
            )
        ),
      
      
      motif_region =
        dplyr::case_when(
          
          motif_end_rel_CDS < 0 ~
            
            "upstream",
          
          
          motif_start_rel_CDS <= 0 &
            motif_end_rel_CDS >= 0 ~
            
            "overlaps_CDS_start",
          
          
          motif_start_rel_CDS > 0 ~
            
            "CDS",
          
          
          TRUE ~
            
            "other"
        )
    )
}



