# ============================================================
# HELPER: FISHER ENRICHMENT TEST
# ============================================================

run_enrichment_test <- function(
    window_table,
    flag_column,
    label
) {
  
  candidate_data <-
    window_table |>
    dplyr::filter(
      dataset ==
        "candidate"
    )
  
  
  background_data <-
    window_table |>
    dplyr::filter(
      dataset ==
        "background"
    )
  
  
  candidate_positive <-
    sum(
      candidate_data[[flag_column]],
      na.rm = TRUE
    )
  
  
  candidate_negative <-
    nrow(
      candidate_data
    ) -
    candidate_positive
  
  
  background_positive <-
    sum(
      background_data[[flag_column]],
      na.rm = TRUE
    )
  
  
  background_negative <-
    nrow(
      background_data
    ) -
    background_positive
  
  
  contingency <- matrix(
    
    c(
      candidate_positive,
      candidate_negative,
      background_positive,
      background_negative
    ),
    
    nrow = 2,
    
    byrow = TRUE,
    
    dimnames =
      list(
        
        Dataset =
          c(
            "Candidate",
            "Background"
          ),
        
        Motif =
          c(
            "Present",
            "Absent"
          )
      )
  )
  
  
  fisher_result <-
    fisher.test(
      contingency,
      alternative =
        "greater"
    )
  
  
  candidate_fraction <-
    candidate_positive /
    nrow(
      candidate_data
    )
  
  
  background_fraction <-
    background_positive /
    nrow(
      background_data
    )
  
  
  fold_enrichment <-
    if (
      background_fraction >
      0
    ) {
      
      candidate_fraction /
        background_fraction
      
    } else {
      
      Inf
    }
  
  
  tibble::tibble(
    
    motif_test =
      label,
    
    candidate_total =
      nrow(
        candidate_data
      ),
    
    candidate_with_motif =
      candidate_positive,
    
    candidate_fraction =
      candidate_fraction,
    
    background_total =
      nrow(
        background_data
      ),
    
    background_with_motif =
      background_positive,
    
    background_fraction =
      background_fraction,
    
    fold_enrichment =
      fold_enrichment,
    
    odds_ratio =
      unname(
        fisher_result$
          estimate
      ),
    
    odds_ratio_CI_low =
      unname(
        fisher_result$
          conf.int[1]
      ),
    
    odds_ratio_CI_high =
      unname(
        fisher_result$
          conf.int[2]
      ),
    
    fisher_p_value =
      fisher_result$
      p.value
  )
}



