    motif_length,
    
    max_mismatches,
    
    expected_window_length,
    
    nrow(
      candidate_windows
    ),
    
    nrow(
      background_windows
    ),
    
    sum(
      candidate_windows$
        has_exact_motif
    ),
    
    sum(
      background_windows$
        has_exact_motif
    ),
    
    sum(
      candidate_windows$
        has_one_mismatch_motif
    ),
    
    sum(
      background_windows$
        has_one_mismatch_motif
    ),
    
    sum(
      candidate_windows$
        has_leq1_mismatch_motif
    ),
    
    sum(
      background_windows$
        has_leq1_mismatch_motif
    ),
    
    nrow(
      motif_occurrences
    )
  )
)



